<script lang="ts">
	import { getContext } from 'svelte';
	import type { i18n as i18nType } from 'i18next';
	import type { Writable } from 'svelte/store';

	const i18n: Writable<i18nType> = getContext<Writable<i18nType>>('i18n');

	interface Props {
		items?: { label: string; href?: string }[];
	}

	let { items = [] }: Props = $props();
</script>

<nav aria-label={$i18n.t('Breadcrumb')} class="flex items-center gap-1 text-xs text-gray-500 dark:text-gray-400 mb-2">
	<a
		href="/admin"
		class="hover:text-gray-700 dark:hover:text-white transition"
	>{$i18n.t('Admin')}</a>

	{#each items as item, i}
		<span class="text-gray-400 dark:text-gray-600">/</span>
		{#if item.href && i < items.length - 1}
			<a
				href={item.href}
				class="hover:text-gray-700 dark:hover:text-white transition"
			>{$i18n.t(item.label)}</a>
		{:else}
			<span class="text-gray-900 dark:text-white font-medium">{$i18n.t(item.label)}</span>
		{/if}
	{/each}
</nav>
